  'Publishing' => 'Publicação',
  '\\nA closed type keeps its history but its forms no longer take payments.\\n' => 'Um tipo fechado mantém seu histórico, mas seus formulários não aceitam mais pagamentos.',
  'Start date' => 'Data de início',
