  '\\nNo recurring donations yet\\n' => 'Ainda não há doações recorrentes',
  '\\nA recurring donation is created when a payment form is set to charge every day, week, month or year.\\n' => 'Uma doação recorrente é criada quando um formulário de pagamento é definido para cobrança diária, semanal, mensal ou anual.',
  '[[\'%srecurring donation\', \'en\']]' . chr(0) . '[[\'%srecurring donations\', \'en\']]' => '%sdoação recorrente' . chr(0) . '%sdoações recorrentes',
