  '\\ncanceled%s\\n' => '\\cancelado%s',
  '\\nCancel this recurring donation at the payment provider? No further charges will be made.\\n' => 'Cancelar esta doação recorrente no provedor de pagamento? Nenhuma cobrança adicional será feita.',
  'WooCommerce' => 'WooCommerce',
  '\\nCard payments: the official iyzico plugin is enabled.\\n' => 'Pagamentos com cartão: o plugin oficial do iyzico está ativado.',
  '\\nCard payments: Flux Donate iyzico (the official iyzico plugin is not enabled).\\n' => 'Pagamentos com cartão: Flux Donate iyzico (o plugin oficial do iyzico não está habilitado).',
  '\\nCard payments:%s.\\n' => 'Pagamentos com cartão: %s.',
