  '\\nMonthly donations are off: enable "Card (iyzico) - Flux Donate" in WooCommerce › Settings › Payments and enter iyzico keys.\\n' => 'As doações mensais estão desativadas: ative "Cartão (iyzico) - Flux Donate" em WooCommerce › Configurações › Pagamentos e insira as chaves do iyzico.',
  '\\nBank transfer (donations)\\n' => 'Transferência bancária (doações)',
  '\\nNo IBAN entered.\\n' => 'Nenhum IBAN inserido.',
  '\\nThe payment method is disabled.\\n' => 'A forma de pagamento está desativada.',
  '\\nBank transfer settings\\n' => 'Configurações de transferência bancária',
  '\\nTwo bank transfer methods\\n' => 'Dois métodos de transferência bancária',
