  '\\nThe shop currency is%1$s; these types use another currency and are charged in%1$sat the same number:%2$s\\n' => 'A moeda da loja é%1$s; esses tipos usam outra moeda e são cobrados em%1$sno mesmo número: %2$s',
  '\\nWooCommerce settings\\n' => 'Configurações do WooCommerce',
  '\\nDonation types and the shop use%s.\\n' => 'Os tipos de doação e a loja usam%s.',
  '\\nDonation products\\n' => 'Produtos para doação',
