  '\\n%dactive type has its hidden WooCommerce product.%dactive types have their hidden WooCommerce products.\\n' => ' O tipo ativo%dtem seu produto WooCommerce oculto. Os tipos ativos%dtêm seus produtos WooCommerce ocultos.',
  '\\nNo page with the donation options block is selected.\\n' => 'Nenhuma página com o bloco de opções de doação foi selecionada.',
  '\\nOther payment plugins\\n' => 'Outros plug-ins de pagamento',
