  '\\nE-mail templates\\n' => 'Modelos de e-mail',
  '\\nFlux Mail is not active: the donation e-mails are sent as plain text with their default wording.\\n' => 'Flux Mail não está ativo: os e-mails de doação são enviados em texto simples com o texto padrão.',
  '\\nBank transfer (donation)\\n' => 'Transferência bancária (doação)',
