  'Enabled' => 'Habilitado',
  '\\nTake donations by bank transfer\\n' => 'Receba doações por transferência bancária',
  'Empty = "Bank transfer" in the site language.' => 'Vazio = "Transferência bancária" no idioma do site.',
  'Text on the checkout page' => 'Texto na página de checkout',
  'Empty = the default text in the site language.' => 'Vazio = o texto padrão no idioma do site.',
  'Recipient (account holder)' => 'Destinatário (titular da conta)',
  '\\nEmpty = the holder of the bank account below or, without an IBAN here, of WooCommerce\\\'s "Direct bank transfer" account (else the theme settings).\\n' => 'Vazio = o titular da conta bancária abaixo ou, sem um IBAN aqui, da conta "Transferência bancária direta" do WooCommerce (caso contrário as configurações do tema).',
