  '\\nUse "Test connection" to check the keys with iyzico.\\n' => 'Use "Testar conexão" para verificar as chaves com iyzico.',
  '\\niyzico keys\\n' => 'iyzico chaves',
  'Test connection' => 'Conexão de teste',
