  '\\nLast notification received:%s.\\n' => 'Última notificação recebida: %s.',
  '\\nNo notification received in the last 30 days (normal until the address is saved in the iyzico panel and a payment is made).\\n' => 'Nenhuma notificação recebida nos últimos 30 dias (normal até que o endereço seja salvo no painel iyzico e o pagamento seja efetuado).',
