  '\\nStripe keys\\n' => 'Teclas de listras',
  '\\nThe Stripe publishable key and secret key are missing.\\n' => 'A chave publicável e a chave secreta do Stripe estão faltando.',
  '\\nMode: live.\\n' => 'Modo: ao vivo.',
  '\\nMode: test (pk_test_). No real money is collected.\\n' => 'Modo: teste (pk_test_). Nenhum dinheiro real é coletado.',
