  '\\nFlux Forms is not active. Donation forms and card payments need it.\\n' => 'Flux Forms não está ativo. Formulários de doação e pagamentos com cartão precisam disso.',
  '\\nActive, version%s.\\n' => 'Ativo, versão%s.',
