  '\\n%1$spaid gift ·%2$s%1$spaid gifts ·%2$s\\n' . chr(0) . '\\n%1$spaid gift ·%2$s%1$spaid gifts ·%2$s\\n' => '%1$spresente pago ·%2$s%1$spresentes pagos ·%2$s' . chr(0) . '%1$spresente pago ·%2$s%1$spresentes pagos ·%2$s',
