  '\\n%sdonation moved to the trash.\\x00%sdonations moved to the trash.\\n' => '%sdoação movida para a lixeira.' . chr(0) . '%sdoações movidas para a lixeira.',
  '\\n%sdonation restored.\\x00%sdonations restored.\\n' => ' Doação%srestaurada.' . chr(0) . '%sdoações restauradas.',
