  '\\n%srecord\\x00%srecords\\n' => 'Registro%s' . chr(0) . ' registros%s',
  '\\n%dwithout a price\\x00%dwithout a price\\n' => '%dsem preço' . chr(0) . '%dsem preço',
  '\\nUsed by%stype\\x00Used by%stypes\\n' => 'Usado pelo tipo%s' . chr(0) . 'Usado pelos tipos%s',
